local sources
function ns.GetEnchantSource(enchantId)
    if not sources then
        local key = ns.IS_RETAIL and "retail" or ((ns.BlizzardStats and ns.BlizzardStats.IsAvailable()) and "forever" or "mop")
        sources = {}
        for id, kind, value in DATA[key]:gmatch("(%d+):(i?)(%d+)") do
            sources[tonumber(id)] = kind == "i" and -tonumber(value) or tonumber(value)
        end
        DATA = nil
    end
    local source = sources[enchantId]
    if not source then return end
    if source < 0 then return nil, -source end
    return source
end
